 "content": "def transform(grid):
    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 2]
    by_row = {}
    for r, c in points:
        by_row.setdefault(r, []).append(c)
    # The pair of markers sharing a row defines the horizontal trunk.
    candidates = [(r, min(cs), max(cs)) for r, cs in by_row.items() if len(cs) >= 2]
    r0, c0, c1 = max(candidates, key=lambda x: x[2] - x[1])
    for c in range(c0 + 1, c1):
        if out[r0][c] == 0:
            out[r0][c] = 3
    # Other markers branch vertically to the trunk at their own columns.
    for r, c in points:
        if r == r0:
            continue
        for rr in range(min(r, r0) + 1, max(r, r0)):
            if out[rr][c] == 0:
                out[rr][c] = 3
    return out
